const settingsMenu=document.createElement('button');
settingsMenu.type='button';settingsMenu.dataset.view='settings';settingsMenu.setAttribute('aria-label','Pengaturan toko');settingsMenu.innerHTML='<svg viewBox="0 0 24 24" fill="none" stroke-width="2"><circle cx="12" cy="12" r="3"/><path d="M19.4 15a1.7 1.7 0 0 0 .3 1.9l.1.1-2.8 2.8-.1-.1a1.7 1.7 0 0 0-1.9-.3 1.7 1.7 0 0 0-1 1.6v.2h-4V21a1.7 1.7 0 0 0-1-1.6 1.7 1.7 0 0 0-1.9.3l-.1.1L4.2 17l.1-.1a1.7 1.7 0 0 0 .3-1.9A1.7 1.7 0 0 0 3 14H2.8v-4H3a1.7 1.7 0 0 0 1.6-1 1.7 1.7 0 0 0-.3-1.9L4.2 7 7 4.2l.1.1a1.7 1.7 0 0 0 1.9.3A1.7 1.7 0 0 0 10 3V2.8h4V3a1.7 1.7 0 0 0 1 1.6 1.7 1.7 0 0 0 1.9-.3l.1-.1L19.8 7l-.1.1a1.7 1.7 0 0 0-.3 1.9 1.7 1.7 0 0 0 1.6 1h.2v4H21a1.7 1.7 0 0 0-1.6 1Z"/></svg><span>Pengaturan</span>';
document.querySelector('.menu').append(settingsMenu);
const settingsView=document.createElement('section');settingsView.className='view';settingsView.id='settings';settingsView.innerHTML='<div class="view-head"><div><h2>Identitas toko</h2><p>Sesuaikan tampilan RuangRupa untuk calon pengguna.</p></div></div><form class="panel" id="storeSettingsForm"><div class="form-grid"><div class="field"><label for="settingStoreName">Nama toko</label><input id="settingStoreName" required maxlength="60"></div><div class="field"><label for="settingTagline">Slogan</label><input id="settingTagline" maxlength="140"></div><div class="field"><label for="settingWhatsapp">Nomor WhatsApp</label><input id="settingWhatsapp" inputmode="tel" placeholder="08xxxxxxxxxx"></div><div class="field"><label for="settingColor">Warna utama</label><input id="settingColor" type="color" value="#2c3a31"></div><div class="field wide"><label for="settingAddress">Alamat usaha</label><textarea id="settingAddress" maxlength="300"></textarea></div><div class="field wide"><label for="settingHeroTitle">Judul halaman utama</label><input id="settingHeroTitle" required maxlength="120"></div><div class="field wide"><label for="settingHeroText">Deskripsi halaman utama</label><textarea id="settingHeroText" required maxlength="300"></textarea></div><div class="field wide"><label for="settingLogo">Logo toko</label><input id="settingLogoUrl" type="hidden"><input id="settingLogo" type="file" accept="image/jpeg,image/png,image/webp"><small>Biarkan kosong untuk menggunakan nama toko sebagai logo.</small><img id="settingLogoPreview" alt="Pratinjau logo" style="display:none;max-width:180px;max-height:80px;object-fit:contain;margin-top:10px"></div></div><div class="form-actions"><button class="primary" type="submit">Simpan pengaturan</button></div></form>';
document.querySelector('.main').append(settingsView);
let selectedLogo=null;
async function loadStoreSettings(){try{const data=await api('/api/store-settings'),settings=data.settings||{};document.querySelector('#settingStoreName').value=settings.storeName||'RuangRupa';document.querySelector('#settingTagline').value=settings.tagline||'';document.querySelector('#settingWhatsapp').value=settings.whatsapp||'';document.querySelector('#settingAddress').value=settings.address||'';document.querySelector('#settingHeroTitle').value=settings.heroTitle||'';document.querySelector('#settingHeroText').value=settings.heroText||'';document.querySelector('#settingColor').value=settings.primaryColor||'#2c3a31';document.querySelector('#settingLogoUrl').value=settings.logoUrl||'';const preview=document.querySelector('#settingLogoPreview');preview.src=settings.logoUrl||'';preview.style.display=settings.logoUrl?'block':'none'}catch(error){toast(error.message)}}
settingsMenu.addEventListener('click',()=>{document.querySelectorAll('.menu button,.view').forEach(item=>item.classList.remove('active'));settingsMenu.classList.add('active');settingsView.classList.add('active');document.querySelector('#pageTitle').textContent='Pengaturan toko';document.querySelector('#pageSubtitle').textContent='Sesuaikan identitas untuk presentasi klien.';loadStoreSettings()});
document.querySelector('#settingLogo').addEventListener('change',event=>{selectedLogo=event.target.files[0]||null;if(!selectedLogo)return;const preview=document.querySelector('#settingLogoPreview');preview.src=URL.createObjectURL(selectedLogo);preview.style.display='block'});
document.querySelector('#storeSettingsForm').addEventListener('submit',async event=>{event.preventDefault();const button=event.submitter;button.disabled=true;button.textContent=selectedLogo?'Mengunggah logo…':'Menyimpan…';try{let logoUrl=document.querySelector('#settingLogoUrl').value;if(selectedLogo){const form=new FormData();form.append('image',selectedLogo);const uploaded=await api('/api/uploads/store-logo',{method:'POST',body:form});logoUrl=uploaded.imageUrl}button.textContent='Menyimpan…';await api('/api/store-settings',{method:'PATCH',body:JSON.stringify({storeName:document.querySelector('#settingStoreName').value,tagline:document.querySelector('#settingTagline').value,whatsapp:document.querySelector('#settingWhatsapp').value,address:document.querySelector('#settingAddress').value,heroTitle:document.querySelector('#settingHeroTitle').value,heroText:document.querySelector('#settingHeroText').value,primaryColor:document.querySelector('#settingColor').value,logoUrl})});selectedLogo=null;toast('Pengaturan toko berhasil disimpan')}catch(error){toast(error.message)}finally{button.disabled=false;button.textContent='Simpan pengaturan'}});

